      s01P2: 'Las cookies pueden ser temporales o persistentes. Una cookie de sesión normalmente desaparece cuando finaliza una sesión del navegador, mientras que una cookie persistente puede permanecer hasta que caduque o sea eliminada.',
      s01P3: 'AmoraLive también puede utilizar tecnologías que cumplen funciones similares a las cookies, incluyendo píxeles, almacenamiento local, identificadores, etiquetas, SDK y otros mecanismos de seguimiento o almacenamiento.',
