      s08P2: 'Los ejemplos pueden incluir proveedores de autenticación, proveedores de análisis, servicios de seguridad, servicios de entrega de contenido, servicios relacionados con pagos o socios publicitarios, según las funciones que AmoraLive opere en un momento determinado.',
      s08P3: 'Los proveedores externos pueden procesar información conforme a sus propias políticas de privacidad y acuerdos contractuales. AmoraLive no controla todas las tecnologías o prácticas utilizadas por terceros independientes.',
      s08NoteTitle: 'TRANSPARENCIA CON TERCEROS',
