      s15P1: 'AmoraLive busca operar sus prácticas de cookies y tecnologías similares de manera coherente con los requisitos legales aplicables.',
      s15P2: 'Para los usuarios de la Unión Europea y del Espacio Económico Europeo, los requisitos pueden surgir del RGPD junto con las normas aplicables que regulan el acceso o almacenamiento de información en los dispositivos de los usuarios, incluidas las implementaciones nacionales del marco de ePrivacy.',
