      faqTitle: 'Preguntas sobre Cookies.',
      faqItems: [
        {
          question: '¿Puedo rechazar las cookies opcionales?',
          answer: 'Sí. Cuando se requiere consentimiento, puedes rechazar las cookies opcionales y tecnologías similares. Rechazar las tecnologías opcionales no debería impedir el acceso a la funcionalidad principal de AmoraLive, a menos que una función en particular dependa genuinamente de la tecnología.'
        },
        {
          question: '¿Puedo cambiar mi decisión más tarde?',
          answer: 'Sí. Cuando AmoraLive proporciona un mecanismo de preferencias de cookies, puedes revisar tus elecciones y retirar o modificar el consentimiento. Retirar el consentimiento debería ser tan fácil como otorgarlo cuando se requiera.'
        },
        {
          question: '¿Eliminar las cookies me cierra la sesión?',
          answer: 'Es posible. Si la información de autenticación o seguridad se almacena mediante cookies o tecnologías similares, eliminar esas tecnologías puede requerir que inicies sesión de nuevo o restablezcas ciertas preferencias.'
        },
        {
          question: '¿AmoraLive usa cookies para vender mis datos personales?',
          answer: 'AmoraLive no tiene la intención de vender datos personales a través de cookies. Cualquier procesamiento que implique tecnologías de terceros sigue sujeto a los requisitos aplicables de privacidad, protección de datos y protección al consumidor.'
        },
        {
          question: '¿Las cookies son la única tecnología de seguimiento?',
          answer: 'No. Los sitios web y aplicaciones también pueden usar tecnologías como píxeles, SDK, almacenamiento local, identificadores de dispositivo, etiquetas o tecnologías similares. Esta política utiliza "cookies y tecnologías similares" cuando corresponde.'
        }
      ],
      finalLabel: 'PROMESA DE PRIVACIDAD DE AMORALIVE',
