      s01Title: 'O Que São Cookies?',
      s01P1: 'Cookies são pequenos arquivos de dados que sites e serviços on-line podem armazenar no dispositivo de um usuário. Eles podem ajudar um serviço a lembrar informações, manter uma sessão, fornecer segurança e entender como um site ou aplicativo está sendo usado.',
      s01P2: 'Os cookies podem ser temporários ou persistentes. Um cookie de sessão normalmente desaparece quando uma sessão do navegador termina, enquanto um cookie persistente pode permanecer até expirar ou ser excluído.',
      s01P3: 'A AmoraLive também pode usar tecnologias que desempenham funções semelhantes aos cookies, incluindo pixels, armazenamento local, identificadores, tags, SDKs e outros mecanismos de rastreamento ou armazenamento.',
