      s08P2: 'Exemplos podem incluir provedores de autenticação, provedores de análises, serviços de segurança, serviços de entrega de conteúdo, serviços relacionados a pagamentos ou parceiros de publicidade, dependendo dos recursos que a AmoraLive opera em um determinado momento.',
      s08P3: 'Os provedores terceirizados podem processar informações de acordo com suas próprias políticas de privacidade e acordos contratuais. A AmoraLive não controla todas as tecnologias ou práticas usadas por terceiros independentes.',
      s08NoteTitle: 'TRANSPARÊNCIA COM TERCEIROS',
