      s01Eyebrow: "APERÇU",
      s01Title: "Que Sont les Cookies ?",
      s01P1: "Les cookies sont de petits fichiers de données que les sites web et services en ligne peuvent stocker sur l'appareil d'un utilisateur. Ils peuvent aider un service à mémoriser des informations, maintenir une session, assurer la sécurité et comprendre comment un site web ou une application est utilisé.",
      s01P2: "Les cookies peuvent être temporaires ou persistants. Un cookie de session disparaît normalement à la fin d'une session de navigateur, tandis qu'un cookie persistant peut rester jusqu'à son expiration ou sa suppression.",
      s01P3: "AmoraLive peut également utiliser des technologies qui remplissent des fonctions similaires aux cookies, notamment des pixels, un stockage local, des identifiants, des balises, des SDK et d'autres mécanismes de suivi ou de stockage.",
      s01InfoTitle: "Les cookies ne sont pas automatiquement « bons » ou « mauvais ».",
      s01InfoBody: "Ce qui compte, c'est pourquoi ils sont utilisés, quelles informations ils traitent, qui peut accéder à ces informations et si la technologie est nécessaire ou requiert un choix de l'utilisateur en vertu de la loi applicable.",
      s02Eyebrow: "POURQUOI NOUS LES UTILISONS",
      s02Title: "Comment AmoraLive Utilise les Cookies",
      s02P1: "Selon les services et fonctionnalités que vous utilisez, AmoraLive peut utiliser des cookies et des technologies similaires aux fins suivantes :",
      purposeGrid: [
        ["Authentification", "Maintenir votre session de connexion et aider à reconnaître votre session authentifiée."],
        ["Sécurité", "Aider à détecter les abus, les activités suspectes, les comportements frauduleux et les accès non autorisés."],
        ["Préférences", "Mémoriser des choix tels que la langue, les paramètres d'interface et d'autres préférences."],
        ["Performance", "Nous aider à comprendre les erreurs, la fiabilité et les performances techniques."],
        ["Analyse", "Comprendre comment les fonctionnalités sont utilisées afin qu'AmoraLive puisse améliorer le service."],
        ["Publicité", "Si des technologies publicitaires sont utilisées, mesurer les campagnes et éventuellement personnaliser la publicité lorsque cela est légalement autorisé."]
      ],
      s03Eyebrow: "CATÉGORIES",
      s03Title: "Types de Cookies et Technologies Similaires",
      s03P1: "Les technologies exactes utilisées par AmoraLive peuvent changer à mesure que la plateforme évolue. Les catégories ci-dessous décrivent les finalités pour lesquelles les technologies peuvent être utilisées.",
