      s04Eyebrow: "TECHNOLOGIES NÉCESSAIRES",
      s04Title: "Cookies Strictement Nécessaires",
      s04P1: "Certains cookies et technologies similaires sont nécessaires au fonctionnement d'AmoraLive. Ils peuvent prendre en charge des fonctions telles que l'authentification, la sécurité, la gestion des sessions, la prévention de la fraude, la répartition de charge et la mémorisation des choix de cookies d'un utilisateur.",
      s04P2: "Selon le cadre juridique applicable et la technologie spécifique, le consentement peut ne pas être requis pour une technologie véritablement nécessaire à la fourniture d'un service explicitement demandé par l'utilisateur.",
      s04ImportantTitle: "IMPORTANT",
      s04ImportantBody: "AmoraLive ne traite pas tous les cookies comme « nécessaires ». Une technologie ne doit être considérée comme nécessaire que lorsque son utilisation est véritablement requise pour le service ou la fonction concernée.",
      s05Eyebrow: "TECHNOLOGIES OPTIONNELLES",
      s05Title: "Analyse, Préférences et Publicité",
      s05P1: "Les technologies optionnelles peuvent fournir des fonctionnalités supplémentaires ou aider AmoraLive à comprendre et à améliorer ses services.",
