      s06P2: "Le consentement ne doit pas être déduit de la simple poursuite de la navigation lorsque la loi applicable exige une action de consentement affirmative. AmoraLive ne décrira pas la simple navigation comme un consentement lorsque cela entrerait en conflit avec les exigences applicables.",
      s07Eyebrow: "CONTRÔLES DU NAVIGATEUR",
      s07Title: "Gérer les Cookies dans Votre Navigateur",
      s07P1: "La plupart des navigateurs modernes permettent aux utilisateurs de bloquer, supprimer ou gérer les cookies. Les contrôles du navigateur varient selon les fournisseurs et les versions.",
