      s07WarningTitle: "VEUILLEZ NOTER",
      s07WarningBody: "Le blocage des cookies nécessaires peut affecter l'authentification, la sécurité, l'accès au compte ou d'autres fonctionnalités essentielles.",
      s08Eyebrow: "TIERS",
      s08Title: "Technologies de Tiers",
      s08P1: "Certaines fonctionnalités d'AmoraLive peuvent dépendre de services fournis par des tiers. Ces fournisseurs peuvent utiliser des cookies ou des technologies similaires lorsque leurs services sont intégrés à AmoraLive.",
      s08P2: "Les exemples peuvent inclure des fournisseurs d'authentification, des fournisseurs d'analyse, des services de sécurité, des services de diffusion de contenu, des services liés aux paiements ou des partenaires publicitaires, selon les fonctionnalités qu'AmoraLive exploite à un moment donné.",
      s08P3: "Les fournisseurs tiers peuvent traiter des informations conformément à leurs propres politiques de confidentialité et accords contractuels. AmoraLive ne contrôle pas toutes les technologies ou pratiques utilisées par des tiers indépendants.",
      s08NoteTitle: "TRANSPARENCE VIS-À-VIS DES TIERS",
      s08NoteBody: "L'inventaire final des cookies présenté aux utilisateurs doit identifier les technologies tierces pertinentes réellement déployées sur le service AmoraLive, leurs finalités, fournisseurs et périodes de conservation applicables.",
      s09Eyebrow: "PROTECTION DES DONNÉES",
      s09Title: "Cookies et Données Personnelles",
      s09P1: "Un identifiant de cookie ou une information associée à un cookie peut constituer une donnée personnelle lorsqu'elle peut être liée, directement ou indirectement, à une personne identifiable.",
