      s10Note: "Le tableau ci-dessus décrit des catégories plutôt qu'un inventaire technique définitif. L'inventaire réel des cookies doit être tenu à jour en fonction des technologies actuellement déployées par AmoraLive.",
      s11Eyebrow: "DROITS EN MATIÈRE DE CONFIDENTIALITÉ",
      s11Title: "Vos Droits en Matière de Protection des Données",
      s11P1: "Selon votre localisation et la loi applicable, vous pouvez disposer de droits concernant les données personnelles traitées par le biais de cookies ou de technologies similaires.",
