      s14P2: "Si vous pensez qu'un enfant a fourni des informations à AmoraLive dans des circonstances où cela n'aurait pas dû se produire, veuillez nous contacter via le canal de confidentialité ou de sécurité approprié.",
      s15Eyebrow: "CADRE JURIDIQUE",
      s15Title: "Conformité Européenne et Suisse",
      s15P1: "AmoraLive vise à exercer ses pratiques en matière de cookies et de technologies similaires de manière cohérente avec les exigences légales applicables.",
      s15P2: "Pour les utilisateurs de l'Union européenne et de l'Espace économique européen, les exigences peuvent découler du RGPD ainsi que des règles applicables régissant l'accès aux informations stockées sur les appareils des utilisateurs ou leur stockage, y compris les mises en œuvre nationales du cadre ePrivacy.",
      s15P3: "Pour les utilisateurs en Suisse, AmoraLive tient également compte des exigences applicables en vertu de la loi suisse sur la protection des données et des directives du Préposé fédéral à la protection des données et à la transparence concernant les cookies et technologies similaires.",
      s15P4: "Les droits et protections obligatoires en vertu de la loi applicable prévalent sur toute déclaration contradictoire dans cette politique.",
      europeCardTitle: "UTILISATEURS EUROPÉENS ET SUISSES",
      europeCardBody: "AmoraLive cherche à fournir des informations transparentes et des choix significatifs concernant les cookies optionnels et les technologies similaires partout où la loi applicable l'exige.",
      s16Eyebrow: "MISES À JOUR",
      s16Title: "Modifications de Cette Politique de Cookies",
      s16P1: "AmoraLive peut mettre à jour cette Politique de Cookies lorsque notre technologie, nos services, nos pratiques commerciales ou nos exigences légales changent.",
      s16P2: "Lorsque des modifications importantes sont apportées, nous pouvons fournir un avis supplémentaire ou demander un consentement mis à jour lorsque la loi applicable l'exige.",
