      faqEyebrow: "QUESTIONS FRÉQUENTES",
      faqTitle: "Questions sur les Cookies.",
      faqItems: [
        {
          question: "Puis-je refuser les cookies optionnels ?",
          answer: "Oui. Lorsque le consentement est requis, vous pouvez refuser les cookies optionnels et les technologies similaires. Refuser les technologies optionnelles ne devrait pas empêcher l'accès aux fonctionnalités essentielles d'AmoraLive, sauf si une fonctionnalité particulière dépend véritablement de la technologie."
        },
        {
          question: "Puis-je changer ma décision plus tard ?",
          answer: "Oui. Lorsqu'AmoraLive fournit un mécanisme de préférence de cookies, vous pouvez revoir vos choix et retirer ou modifier votre consentement. Le retrait devrait être aussi simple que de donner son consentement lorsque celui-ci est requis."
        },
        {
          question: "La suppression des cookies me déconnecte-t-elle ?",
          answer: "Cela se peut. Si des informations d'authentification ou de sécurité sont stockées à l'aide de cookies ou de technologies similaires, la suppression de ces technologies peut vous obliger à vous reconnecter ou à réinitialiser certaines préférences."
        },
        {
          question: "AmoraLive utilise-t-elle des cookies pour vendre mes données personnelles ?",
          answer: "AmoraLive n'a pas l'intention de vendre des données personnelles par le biais de cookies. Tout traitement impliquant des technologies tierces reste soumis aux exigences applicables en matière de confidentialité, de protection des données et de protection des consommateurs."
        },
        {
          question: "Les cookies sont-ils la seule technologie de suivi ?",
          answer: "Non. Les sites web et applications peuvent également utiliser des technologies telles que des pixels, des SDK, un stockage local, des identifiants d'appareil, des balises ou des technologies similaires. Cette politique utilise « cookies et technologies similaires » le cas échéant."
        }
      ],
