      acceptanceP1: 'Durch die Erstellung eines Kontos, den Zugriff auf, das Durchsuchen von oder die Nutzung von AmoraLive stimmen Sie diesen Nutzungsbedingungen und den darin enthaltenen Richtlinien zu.',
