      eligibilityP1: 'AmoraLive richtet sich an Erwachsene. Sie müssen mindestens 18 Jahre alt sein, um ein AmoraLive-Konto zu erstellen oder zu nutzen, es sei denn, AmoraLive bietet ausdrücklich einen rechtskonformen Dienst für eine jüngere Altersgruppe an.',
