      accountP1: 'Sie sind für den Schutz Ihrer Kontodaten und für Aktivitäten über Ihr Konto verantwortlich, außer wenn unbefugter Zugriff auf Umstände zurückzuführen ist, für die AmoraLive rechtlich verantwortlich ist.',
