      contentP1: 'Nutzer können Text, Fotos, Videos, Audio, Livestreams, Kommentare, Benutzernamen, Profilinformationen und andere Inhalte hochladen, veröffentlichen, übertragen oder anderweitig zugänglich machen.',
      contentP2: 'Sie bleiben für die von Ihnen eingereichten Inhalte verantwortlich und müssen über alle Rechte, Genehmigungen und Rechtsgrundlagen verfügen, die erforderlich sind, um diese Inhalte AmoraLive zur Verfügung zu stellen.',
      contentQuote: 'Ihre Inhalte bleiben Ihre. AmoraLive erhält nur die Berechtigungen, die zum Betrieb des Dienstes vernünftigerweise erforderlich sind.',
