      safetyP1: 'AmoraLive ist darauf ausgelegt, den Nutzern eine sichere Umgebung zu bieten. Belästigung, Drohungen, Mobbing, Stalking, Nötigung und missbräuchliches Verhalten sind verboten.',
      safetyP2: 'Nutzer sollten schwerwiegendes oder potenziell rechtswidriges Verhalten über die Meldemechanismen von AmoraLive melden und gegebenenfalls die zuständigen Behörden kontaktieren.',
      liveP1: 'Livestream-Hosts sind für Inhalte und Verhalten während ihrer Übertragungen verantwortlich.',
