      expressionP1: 'AmoraLive respektiert die Meinungsfreiheit und andere Grundrechte.',
      expressionP2: 'Die Meinungsfreiheit begründet kein Recht, AmoraLive für rechtswidriges Verhalten, Drohungen, Belästigung, Ausbeutung, Betrug, Datenschutzverletzungen oder andere verbotene Aktivitäten zu nutzen.',
      expressionP3: 'Die Inhaltsmoderation erfolgt vorbehaltlich geltenden Rechts und der berechtigten Sicherheits- und Integritätsanforderungen der Plattform.',
      ipP1: 'Die Software, Marken, Logos, Designs, Schnittstellen, Animationen, Grafiken, Datenbanken und anderen Plattformmaterialien von AmoraLive sind durch Gesetze zum geistigen Eigentum geschützt.',
      ipP2: 'Außer soweit gesetzlich zulässig oder von AmoraLive ausdrücklich genehmigt, dürfen Sie geschützte Plattformmaterialien nicht kopieren, ändern, verbreiten, verkaufen, zurückentwickeln oder kommerziell nutzen.',
