      minorsP3: 'Wo gesetzlich vorgeschrieben, wird AmoraLive zusätzliche Schutzmaßnahmen in Bezug auf Minderjährige anwenden, einschließlich angemessener Datenschutz- und Sicherheitsmaßnahmen.',
      aiP1: 'AmoraLive kann automatisierte Systeme, künstliche Intelligenz, maschinelles Lernen oder algorithmische Werkzeuge für Sicherheit, Moderation, Empfehlungen, Betrugserkennung, Personalisierung, Übersetzung und andere legitime Plattformfunktionen nutzen.',
      aiP2: 'Wo geltendes Recht spezifische Rechte in Bezug auf automatisierte Entscheidungen vorsieht, wird AmoraLive die gesetzlich erforderlichen Informationen und Schutzmaßnahmen bereitstellen.',
      thirdpartyP1: 'AmoraLive kann Dienste Dritter integrieren, einschließlich Zahlungsdienstleistern, Authentifizierungsanbietern, Cloud-Infrastruktur, Analysediensten und Kommunikationstechnologien.',
      thirdpartyP2: 'Dienste Dritter können eigene Bedingungen und Datenschutzerklärungen haben. AmoraLive ist nicht verantwortlich für unabhängige Dienste, die von Dritten betrieben werden, außer wenn die Haftung rechtlich nicht ausgeschlossen werden kann.',
      availabilityP1: 'AmoraLive kann Funktionen aktualisieren, ändern, aussetzen oder einstellen. Wartung, Sicherheitsvorfälle, Infrastrukturausfälle und Ereignisse außerhalb angemessener Kontrolle können die Verfügbarkeit vorübergehend beeinträchtigen.',
      availabilityP2: 'Wo gesetzlich vorgeschrieben, erhalten Nutzer angemessene Mitteilung über wesentliche Änderungen oder die Einstellung.',
      terminationP1: 'AmoraLive kann Konten aussetzen oder kündigen, soweit dies angemessen erforderlich ist, um diese Bedingungen durchzusetzen, Nutzer zu schützen, Betrug zu verhindern, Gesetze einzuhalten oder die Sicherheit und Integrität des Dienstes zu schützen.',
      terminationP2: 'Wo gesetzlich vorgeschrieben, wird AmoraLive eine angemessene Erklärung und/oder einen Einspruchsmechanismus bereitstellen.',
      liabilityP1: 'Im größtmöglichen gesetzlich zulässigen Umfang garantiert AmoraLive nicht, dass der Dienst immer unterbrechungsfrei, fehlerfrei, sicher oder an jedem Ort verfügbar ist.',
      liabilityP2: 'Nichts in diesen Bedingungen schließt eine Haftung aus oder beschränkt sie, die rechtlich nicht ausgeschlossen oder beschränkt werden kann.',
      liabilityLabel: 'RECHTLICHER SCHUTZ', liabilityBadge: 'Zwingende gesetzliche Rechte bleiben unberührt.',
      internationalP1: 'AmoraLive kann international zugänglich sein. Nutzer sind dafür verantwortlich, die für sie geltenden Gesetze bei der Nutzung des Dienstes einzuhalten.',
      internationalP2: 'AmoraLive garantiert nicht, dass jede Funktion in jedem Land verfügbar oder rechtmäßig ist.',
      disputesP1: 'AmoraLive ermutigt Nutzer, sich zunächst an den Support zu wenden, damit Streitigkeiten effizient gelöst werden können.',
      disputesP2: 'Die endgültigen Bestimmungen zum anwendbaren Recht und zum zuständigen Gericht sollten die tatsächliche Vertragspartei und den Gerichtsstand benennen. Eine solche Klausel unterliegt weiterhin zwingenden Verbraucherschutz- und anderen gesetzlichen Schutzbestimmungen, auf die rechtlich nicht verzichtet werden kann.',
      disputesPlaceholderLabel: 'VOR VERÖFFENTLICHUNG ERFORDERLICH', disputesPlaceholderText: 'Verifizierte juristische Person + Gerichtsstand einfügen.',
      changesP1: 'AmoraLive kann diese Bedingungen bei angemessener Notwendigkeit aktualisieren, unter anderem um Änderungen am Dienst, an der Technologie, am geltenden Recht, an Sicherheitsanforderungen oder Geschäftsabläufen widerzuspiegeln.',
      changesP2: 'Wesentliche Änderungen werden in angemessener Weise mitgeteilt, wo gesetzlich vorgeschrieben.',
      contactP1: 'Rechtliche Mitteilungen und förmliche Supportanfragen sollten über den offiziellen rechtlichen oder Support-Kanal von AmoraLive gesendet werden.',
