      profileP1: 'AmoraLive ist eine soziale Plattform. Informationen, die du auf deinem öffentlichen oder halböffentlichen Profil platzierst, können je nach deinen Einstellungen und der betreffenden Funktion für andere Nutzer sichtbar sein.',
      profileP2: 'Bevor du persönliche Informationen über eine andere Person veröffentlichst, solltest du über eine geeignete Rechtsgrundlage oder Erlaubnis dafür verfügen.',
      profileWarningTitle: 'Denke nach, bevor du veröffentlichst.',
      profileWarningBody: 'Öffentlich veröffentlichte Informationen können von anderen Nutzern kopiert, per Screenshot festgehalten oder weiterverbreitet werden. Datenschutzeinstellungen können nicht garantieren, dass andere Nutzer Informationen, die sie rechtmäßig eingesehen haben, nicht behalten.',
