      liveP2: 'Je nach Funktion kann Livestream-Inhalt für andere Nutzer sichtbar sein und für einen durch die Produktkonfiguration bestimmten Zeitraum verfügbar bleiben.',
      liveP3: 'AmoraLive kann livestreambezogene Informationen für Sicherheit, Moderation, Betrugsprävention, Servicebetrieb und Rechtskonformität verarbeiten.',
