      messagesP3: 'AmoraLive erklärt nicht, dass private Nachrichten Ende-zu-Ende-verschlüsselten Kommunikationen entsprechen, es sei denn, die spezifische Funktion gibt ausdrücklich an, dass sie Ende-zu-Ende-Verschlüsselung bietet.',
      messagesSecurityTitle: 'Sicherheit ist nicht dasselbe wie Anonymität.',
