      giftsP1: 'Wenn du Coins, digitale Geschenke, Mitgliedschaften oder andere kostenpflichtige Funktionen kaufst, können AmoraLive und seine Zahlungsanbieter transaktionsbezogene Informationen verarbeiten.',
