      moderationP3: 'AmoraLive kann sofortige Maßnahmen ergreifen, wenn dies notwendig ist, um Nutzer zu schützen, Beweise zu sichern, anhaltenden Schaden zu verhindern oder rechtlichen Verpflichtungen nachzukommen.',
      appealsP1: 'Sofern ein Einspruchsmechanismus verfügbar ist, können Nutzer gemäß dem geltenden Verfahren eine Überprüfung einer Durchsetzungsentscheidung beantragen.',
      appealsP2: 'Einsprüche sollten relevante Informationen enthalten, die erklären, warum der Nutzer die Entscheidung für falsch hält.',
      appealsP3: 'AmoraLive kann Einschränkungen während der Prüfung eines Einspruchs aufrechterhalten, wenn dies notwendig ist, um Nutzer zu schützen oder fortgesetzten Missbrauch zu verhindern.',
      lawP1: 'Diese Richtlinien gelten zusätzlich zu den Nutzungsbedingungen, der Datenschutzerklärung und anderen geltenden Richtlinien von AmoraLive.',
      lawP2: 'AmoraLive kann gültigen rechtlichen Verpflichtungen, rechtmäßigen Anordnungen und Anfragen zuständiger Behörden nachkommen, sofern gesetzlich vorgeschrieben.',
      lawP3: 'Nichts in diesen Richtlinien soll Rechte oder Schutzmaßnahmen aufheben, die Nutzern nach zwingendem geltendem Recht zustehen.',
      lawCardTitle: 'EUROPÄISCHE UND SCHWEIZER NUTZER',
      lawCardBody: 'Sofern zwingende Verbraucher-, Digitaldienste-, Datenschutz- oder andere Schutzbestimmungen gelten, wird AmoraLive bestrebt sein, seine Dienste im Einklang mit diesen Anforderungen zu betreiben.',
      changesP1: 'AmoraLive kann diese Community-Richtlinien aktualisieren, wenn sich die Plattform weiterentwickelt, neue Sicherheitsrisiken auftreten oder sich rechtliche und regulatorische Anforderungen ändern.',
      changesP2: 'Das am Anfang dieser Seite angezeigte Inkrafttretensdatum kennzeichnet die aktuelle Version.',
      changesP3: 'Die fortgesetzte Nutzung von AmoraLive nach Inkrafttreten geltender Änderungen unterliegt den aktualisierten Richtlinien, soweit gesetzlich zulässig.',
      finalLabel: 'AMORALIVE COMMUNITY-VERSPRECHEN',
      finalTitle: 'Mach AmoraLive Besser.',
