      s01Eyebrow: 'ÜBERBLICK',
      s01Title: 'Was Sind Cookies?',
      s01P1: 'Cookies sind kleine Datendateien, die Websites und Online-Dienste auf dem Gerät eines Nutzers speichern können. Sie können einem Dienst helfen, Informationen zu speichern, eine Sitzung aufrechtzuerhalten, Sicherheit zu gewährleisten und zu verstehen, wie eine Website oder Anwendung genutzt wird.',
      s01P2: 'Cookies können temporär oder dauerhaft sein. Ein Sitzungscookie verschwindet normalerweise, wenn eine Browsersitzung endet, während ein dauerhaftes Cookie bestehen bleiben kann, bis es abläuft oder gelöscht wird.',
      s01P3: 'AmoraLive kann auch Technologien verwenden, die ähnliche Funktionen wie Cookies erfüllen, einschließlich Pixel, lokalem Speicher, Kennungen, Tags, SDKs und anderen Tracking- oder Speichermechanismen.',
      s01InfoTitle: 'Cookies sind nicht automatisch „gut“ oder „schlecht“.',
      s01InfoBody: 'Entscheidend ist, warum sie verwendet werden, welche Informationen sie verarbeiten, wer auf diese Informationen zugreifen kann und ob die Technologie notwendig ist oder nach geltendem Recht eine Nutzerwahl erfordert.',
      s02Eyebrow: 'WARUM WIR SIE VERWENDEN',
      s02Title: 'Wie AmoraLive Cookies Verwendet',
      s02P1: 'Je nach den von dir genutzten Diensten und Funktionen kann AmoraLive Cookies und ähnliche Technologien für die folgenden Zwecke verwenden:',
