        ['Leistung', 'Uns helfen, Fehler, Zuverlässigkeit und technische Leistung zu verstehen.'],
        ['Analyse', 'Verstehen, wie Funktionen genutzt werden, damit AmoraLive den Dienst verbessern kann.'],
        ['Werbung', 'Falls Werbetechnologien verwendet werden, Kampagnen messen und Werbung, sofern gesetzlich zulässig, möglicherweise personalisieren.']
