      s04Eyebrow: 'NOTWENDIGE TECHNOLOGIEN',
      s04Title: 'Unbedingt Erforderliche Cookies',
      s04P1: 'Einige Cookies und ähnliche Technologien sind für den Betrieb von AmoraLive notwendig. Sie können Funktionen wie Authentifizierung, Sicherheit, Sitzungsverwaltung, Betrugsprävention, Lastverteilung und das Speichern der Cookie-Entscheidungen eines Nutzers unterstützen.',
      s04P2: 'Je nach geltendem Rechtsrahmen und der spezifischen Technologie ist möglicherweise keine Einwilligung erforderlich für eine Technologie, die für die Bereitstellung eines vom Nutzer ausdrücklich angeforderten Dienstes wirklich notwendig ist.',
      s04ImportantTitle: 'WICHTIG',
      s04ImportantBody: 'AmoraLive behandelt nicht jedes Cookie als „notwendig“. Eine Technologie sollte nur dann als notwendig gelten, wenn ihre Verwendung für den betreffenden Dienst oder die Funktion wirklich erforderlich ist.',
      s05Eyebrow: 'OPTIONALE TECHNOLOGIEN',
      s05Title: 'Analyse, Einstellungen & Werbung',
      s05P1: 'Optionale Technologien können zusätzliche Funktionalität bieten oder AmoraLive helfen, seine Dienste zu verstehen und zu verbessern.',
      s05P2: 'Sofern geltendes Recht eine Einwilligung verlangt, bevor ein bestimmtes Cookie oder eine ähnliche Technologie gespeichert oder abgerufen wird, wird AmoraLive die erforderliche Einwilligung einholen, bevor diese Technologie aktiviert wird.',
      s05P3: 'Die Ablehnung optionaler Technologien sollte den Zugang zu den Kerndiensten von AmoraLive nicht verhindern, es sei denn, eine bestimmte Funktion erfordert wirklich die betreffende Technologie.',
      s06Eyebrow: 'DEINE ENTSCHEIDUNGEN',
      s06Title: 'Cookie-Einwilligung und Deine Kontrolle',
      s06P1: 'Sofern eine Einwilligung erforderlich ist, möchte AmoraLive Nutzern aussagekräftige Entscheidungsmöglichkeiten in Bezug auf optionale Cookies und ähnliche Technologien bieten.',
      choiceGrid: [
        ['Akzeptieren', 'Die in der Einwilligungsoberfläche vorgestellten optionalen Kategorien zulassen.'],
        ['Ablehnen', 'Optionale Technologien ablehnen, sofern die Einwilligungsoberfläche diese Wahl bietet.'],
        ['Anpassen', 'Einzelne optionale Kategorien auswählen, wenn granulare Kontrollen verfügbar sind.'],
        ['Widerrufen', 'Deine Einstellungen überprüfen und die Einwilligung widerrufen, sofern der entsprechende Einwilligungsmechanismus verfügbar ist.']
      ],
      s06P2: 'Eine Einwilligung sollte nicht allein aus fortgesetztem Browsen abgeleitet werden, wenn geltendes Recht eine ausdrückliche Einwilligungshandlung verlangt. AmoraLive wird bloßes Browsen nicht als Einwilligung bezeichnen, wenn dies mit geltenden Anforderungen kollidieren würde.',
      s07Eyebrow: 'BROWSER-EINSTELLUNGEN',
      s07Title: 'Cookies in Deinem Browser Verwalten',
      s07P1: 'Die meisten modernen Browser ermöglichen es Nutzern, Cookies zu blockieren, zu löschen oder zu verwalten. Die Browsereinstellungen unterscheiden sich zwischen Anbietern und Versionen.',
      browserBullets: [
        'Vorhandene Cookies von deinem Gerät löschen.',
        'Einige oder alle Cookies blockieren.',
        'Warnungen erhalten, wenn Cookies gespeichert werden.',
        'Websitespezifische Cookie-Berechtigungen konfigurieren.'
      ],
      s07WarningTitle: 'BITTE BEACHTEN',
      s07WarningBody: 'Das Blockieren notwendiger Cookies kann Authentifizierung, Sicherheit, Kontozugang oder andere Kernfunktionen beeinträchtigen.',
      s08Eyebrow: 'DRITTANBIETER',
      s08Title: 'Technologien von Drittanbietern',
      s08P1: 'Einige AmoraLive-Funktionen können von Diensten Dritter abhängen. Diese Anbieter können Cookies oder ähnliche Technologien verwenden, wenn ihre Dienste in AmoraLive integriert sind.',
      s08P2: 'Beispiele können Authentifizierungsanbieter, Analyseanbieter, Sicherheitsdienste, Content-Delivery-Dienste, zahlungsbezogene Dienste oder Werbepartner umfassen, je nachdem, welche Funktionen AmoraLive zu einem bestimmten Zeitpunkt betreibt.',
      s08P3: 'Drittanbieter können Informationen gemäß ihren eigenen Datenschutzrichtlinien und vertraglichen Vereinbarungen verarbeiten. AmoraLive kontrolliert nicht jede Technologie oder Praxis, die von unabhängigen Dritten verwendet wird.',
      s08NoteTitle: 'TRANSPARENZ GEGENÜBER DRITTANBIETERN',
      s08NoteBody: 'Das den Nutzern angezeigte endgültige Cookie-Inventar sollte relevante, tatsächlich auf dem AmoraLive-Dienst eingesetzte Drittanbietertechnologien, deren Zwecke, Anbieter und geltende Aufbewahrungsfristen identifizieren.',
      s09Eyebrow: 'DATENSCHUTZ',
      s09Title: 'Cookies und Personenbezogene Daten',
      s09P1: 'Eine Cookie-Kennung oder eine mit einem Cookie verknüpfte Information kann personenbezogene Daten darstellen, wenn sie direkt oder indirekt mit einer identifizierbaren Person verknüpft werden kann.',
      s09P2: 'Sofern Cookies oder ähnliche Technologien personenbezogene Daten betreffen, verarbeitet AmoraLive diese Informationen gemäß seiner Datenschutzerklärung und dem geltenden Datenschutzrecht.',
      s09P3: 'Je nach den Umständen können anwendbare Rechtsrahmen europäische Datenschutzanforderungen wie die DSGVO, nationale ePrivacy-Vorschriften und schweizerische Datenschutzanforderungen umfassen, sofern anwendbar.',
