      s10Eyebrow: 'AUFBEWAHRUNG',
      s10Title: 'Wie Lange Cookies Bestehen Bleiben',
      s10P1: 'Cookies können sitzungsbasiert oder dauerhaft sein. Der Zeitraum, für den eine bestimmte Technologie aktiv bleibt, hängt von ihrem Zweck und ihrer technischen Konfiguration ab.',
      s10P2: 'AmoraLive kann kurzlebige Technologien für eine einzelne Sitzung und länger anhaltende Technologien für Einstellungen, Sicherheit, Einwilligungsaufzeichnungen oder andere legitime Zwecke verwenden.',
      retentionHeader: ['TYP', 'ALLGEMEINER ZWECK', 'LEBENSDAUER'],
