        'Einschränkung der Verarbeitung unter bestimmten Umständen verlangen.',
        'Bestimmten Verarbeitungstätigkeiten widersprechen.',
        'Datenübertragbarkeit verlangen, sofern anwendbar.',
        'Einwilligung widerrufen, sofern die Verarbeitung auf Einwilligung beruht.'
