      s08NoteTitle: 'तीसरे पक्ष की पारदर्शिता',
      s08NoteBody: 'उपयोगकर्ताओं को दिखाए गए अंतिम कुकी सूची में अमोरालाइव सेवा पर वास्तव में तैनात संबंधित तीसरे पक्ष की तकनीकों, उनके उद्देश्यों, प्रदाताओं और लागू प्रतिधारण अवधियों की पहचान होनी चाहिए।',
