      minorsP1: 'AmoraLive menganggap serius keselamatan anak-anak dan remaja.',
      minorsP2: 'Konten atau perilaku yang mengeksploitasi, menyeksualisasi, atau membahayakan anak di bawah umur sangat dilarang.',
      minorsP3: 'Jika diwajibkan secara hukum, AmoraLive akan menerapkan perlindungan tambahan terkait anak di bawah umur, termasuk langkah-langkah privasi dan keamanan yang sesuai.',
      aiP1: 'AmoraLive dapat menggunakan sistem otomatis, kecerdasan buatan, pembelajaran mesin, atau alat algoritmik untuk keamanan, moderasi, rekomendasi, deteksi penipuan, personalisasi, terjemahan, dan fungsi platform yang sah lainnya.',
      aiP2: 'Jika hukum yang berlaku memberikan hak khusus terkait keputusan otomatis, AmoraLive akan menyediakan informasi dan perlindungan yang diwajibkan secara hukum.',
      thirdpartyP1: 'AmoraLive dapat mengintegrasikan layanan pihak ketiga termasuk penyedia pembayaran, penyedia autentikasi, infrastruktur cloud, layanan analitik, dan teknologi komunikasi.',
      thirdpartyP2: 'Layanan pihak ketiga mungkin memiliki syarat dan kebijakan privasi sendiri. AmoraLive tidak bertanggung jawab atas layanan independen yang dioperasikan oleh pihak ketiga, kecuali jika tanggung jawab tidak dapat dikecualikan secara hukum.',
      availabilityP1: 'AmoraLive dapat memperbarui, memodifikasi, menangguhkan, atau menghentikan fitur. Pemeliharaan, insiden keamanan, kegagalan infrastruktur, dan peristiwa di luar kendali yang wajar dapat memengaruhi ketersediaan untuk sementara.',
      availabilityP2: 'Jika diwajibkan secara hukum, pengguna akan menerima pemberitahuan yang sesuai tentang perubahan material atau penghentian layanan.',
      terminationP1: 'AmoraLive dapat menangguhkan atau menghentikan akun jika secara wajar diperlukan untuk menegakkan Syarat ini, melindungi pengguna, mencegah penipuan, mematuhi hukum, atau melindungi keamanan dan integritas layanan.',
      terminationP2: 'Jika diwajibkan oleh hukum yang berlaku, AmoraLive akan memberikan penjelasan yang sesuai dan/atau mekanisme banding.',
      liabilityP1: 'Sejauh diizinkan oleh hukum yang berlaku, AmoraLive tidak menjamin bahwa layanan akan selalu tanpa gangguan, bebas kesalahan, aman, atau tersedia di setiap lokasi.',
      liabilityP2: 'Tidak ada dalam Syarat ini yang mengecualikan atau membatasi tanggung jawab yang secara hukum tidak dapat dikecualikan atau dibatasi.',
      liabilityLabel: 'PERLINDUNGAN HUKUM', liabilityBadge: 'Hak-hak hukum yang wajib tetap tidak terpengaruh.',
      internationalP1: 'AmoraLive dapat diakses secara internasional. Pengguna bertanggung jawab untuk mematuhi hukum yang berlaku bagi mereka saat menggunakan layanan.',
      internationalP2: 'AmoraLive tidak menyatakan bahwa setiap fitur tersedia atau sah di setiap negara.',
      disputesP1: 'AmoraLive mendorong pengguna untuk menghubungi dukungan terlebih dahulu agar sengketa dapat diselesaikan secara efisien.',
      disputesP2: 'Ketentuan akhir hukum yang berlaku dan pengadilan yang berwenang harus mengidentifikasi entitas kontrak yang sebenarnya dan yurisdiksi. Klausul semacam itu tetap tunduk pada perlindungan konsumen wajib dan perlindungan hukum lainnya yang secara hukum tidak dapat dikesampingkan.',
      disputesPlaceholderLabel: 'DIPERLUKAN SEBELUM DIPUBLIKASIKAN', disputesPlaceholderText: 'Masukkan entitas hukum yang terverifikasi + yurisdiksi.',
